import sys


def main():
    counters = [0] * 6
    slugs = {}
    in_code_block = False

    for line in sys.stdin:
        line = line.rstrip("\n")

        # Check if we are inside a code block
        if line.startswith("```"):
            in_code_block = not in_code_block
            continue

        if in_code_block:
            continue

        if not line.startswith("#"):
            continue

        level = len(line) - len(line.lstrip("#"))
        if level > 6:
            continue

        text = line[level:].strip()
        if not text:
            continue

        # Remove trailing hashes and spaces
        while text.endswith("# ") or text.endswith("#"):
            text = text[:-1].rstrip()
        while text.startswith(" "):
            text = text[1:]
        while text.endswith(" "):
            text = text[:-1]

        counters[level - 1] += 1
        for i in range(level, 6):
            counters[i] = 0
        number = ".".join(str(c) for c in counters[:level])

        # Build slug: replace spaces with hyphens, remove other non-alphanumeric characters
        slug = "".join(c if c.isalnum() or c == "-" else "-" for c in text.lower())

        suffix = 1
        while slug in slugs:
            slug = f"{slug}-{suffix}"
            suffix += 1
        slugs[slug] = True

        print("  " * (level - 1) + f"{number} {text} (#{slug})")


if __name__ == "__main__":
    main()
